exercises.solution:
class Book {
  constructor(title, pages) {
    this.title = title;
    this.pages = pages;
  }
  summary() {
    return `${this.title} (${this.pages} pages)`;
  }
}
const b = new Book("Dune", 412);
console.log(b.summary());

