exercises.solution:
class Person {
  #age = 0;
  setAge(n) {
    if (n >= 0) this.#age = n;
  }
  getAge() { return this.#age; }
}
const p = new Person();
p.setAge(20);
p.setAge(-5);
console.log("age:", p.getAge());
